import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();



export type ImpactListProps = Record<string, any>;

const ImpactList: React.FC<ImpactListProps> = ({
  backgroundColor = "#FAF9F6",
  transparentBackground = false,
  durationInSeconds = 12,
  title = "Our Impact",
  textColor = "#1C1917",
  accentColor = "#B45309",
  items = [
    "Scholarships could be funded.",
    "Buildings maintained.",
    "Outreach expanded.",
    "Mission work supported.",
    "Future generations discipled.",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Logic to prevent parser errors for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Title Animations (Slower fade and glide)
  const titleOpacity = interpolate(frame, [15, 60], [0, 1], { extrapolateRight: "clamp" });
  const titleSpring = spring({ 
    frame: Math.max(0, frame - 15), 
    fps, 
    config: { damping: 16, stiffness: 40 } 
  });
  const titleY = interpolate(titleSpring, [0, 1], [-40, 0]);

  // Layout calculations optimized for 16:9
  const safeZone = width * 0.1;
  const contentWidth = width * 0.6; // ~60% of the canvas for readability

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "flex-start",
          width: "100%",
          height: "100%",
          paddingLeft: `${safeZone}px`,
          paddingRight: `${safeZone}px`,
          boxSizing: "border-box",
        }}
      >
        <div style={{ maxWidth: `${contentWidth}px` }}>
          {/* Animated Title */}
          <h1
            style={{
              fontFamily: playfairFamily,
              fontSize: "84px",
              fontWeight: 700,
              color: textColor,
              margin: 0,
              marginBottom: "80px",
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              transition: "none",
            }}
          >
            {title}
            <span style={{ color: accentColor }}>.</span>
          </h1>

          {/* Animated List */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "40px",
            }}
          >
            {items.map((item, index) => {
              // Stagger each item by 30 frames for a slower paced list reveal
              const staggerDelay = 50 + index * 30;
              const itemFrame = Math.max(0, frame - staggerDelay);

              const itemOpacity = interpolate(itemFrame, [0, 30], [0, 1], {
                extrapolateRight: "clamp",
              });

              // Slower item slide animation
              const itemSlideSpring = spring({
                frame: itemFrame,
                fps,
                config: { damping: 16, stiffness: 40 },
              });
              
              const itemX = interpolate(itemSlideSpring, [0, 1], [-60, 0]);
              const lineScale = interpolate(itemSlideSpring, [0, 1], [0, 1]);

              return (
                <div
                  key={index}
                  style={{
                    display: "flex",
                    flexDirection: "row",
                    alignItems: "center",
                    opacity: itemOpacity,
                    transform: `translateX(${itemX}px)`,
                    transition: "none",
                  }}
                >
                  {/* Accent Line / Bullet Indicator */}
                  <div
                    style={{
                      width: "48px",
                      height: "4px",
                      backgroundColor: accentColor,
                      marginRight: "32px",
                      transform: `scaleX(${lineScale})`,
                      transformOrigin: "left center",
                      flexShrink: 0,
                      transition: "none",
                    }}
                  />
                  {/* Text Item */}
                  <span
                    style={{
                      fontFamily: interFamily,
                      fontSize: "48px",
                      fontWeight: 400,
                      color: textColor,
                      lineHeight: 1.2,
                      transition: "none",
                    }}
                  >
                    {item}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ImpactList;